mapper.select:
SELECT 
FROM `t_supporting_facilities` f
WHERE f.`crzdbh` = #{crzdbh}

    AND f.`ptxmmc` LIKE CONCAT('%', #{keyword}, '%')

ORDER BY f.`ptxmmc`
LIMIT #{limit}

SELECT FROM `t_supporting_facilities` f
(f.`ptxmmc` LIKE CONCAT('%', #{keyword}, '%') OR f.`crzdbh` LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY f.`crzdbh`, f.`ptxmmc` LIMIT #{limit}
